INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein WLAN-Zugangspunkt immer Internet braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch lokal verbinden"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend, um mehrere Geräte drahtlos zu verbinden?', 3, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Ermöglicht stabile Verbindungen"}, {"text": "Kleine Reichweite", "correct": false, "because": "Einschränkend"}, {"text": "Bunte LEDs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern eine drahtlose Verbindung?', 5, '[{"text": "WPA3-Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "Passwortschutz", "correct": true, "because": "Verhindert Zugriff"}, {"text": "Hohe Frequenz", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Großer Akku", "correct": false, "because": "Nur Laufzeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein mobiler Zugangspunkt nutzt Mobilfunk. b) Er ersetzt feste Router.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Zugangspunkt für unterwegs einrichte?', 4, '[{"text": "Signalreichweite", "correct": false, "because": "Bestimmt Abdeckung"}, {"text": "Sicherheitsprotokolle", "correct": false, "because": "Schützen Daten"}, {"text": "Gerätefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein mobiler Zugangspunkt immer 5G braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch 4G oder WLAN möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für einen öffentlichen Zugangspunkt?', 3, '[{"text": "WPA2-Enterprise", "correct": true, "because": "Sichert Nutzer individuell"}, {"text": "Offenes Netz", "correct": false, "because": "Unsicher"}, {"text": "WEP", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein tragbarer Zugangspunkt?', 5, '[{"text": "Mobilität", "correct": true, "because": "Überall nutzbar"}, {"text": "Eigene Datenverbindung", "correct": true, "because": "Unabhängig von WLAN"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Irrelevant"}, {"text": "Feste Installation", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) ein Zugangspunkt mehrere Geräte verbindet und b) er immer Strom braucht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Akkus möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen mobilen Zugangspunkt?', 4, '[{"text": "SIM-Karte", "correct": false, "because": "Für Mobilfunk nötig"}, {"text": "Passwort", "correct": false, "because": "Sichert Zugang"}, {"text": "Bürostuhl", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Zugangspunkt ohne Internet nutzlos?', 2, '[{"text": "Nein", "correct": true, "because": "Kann lokal verbinden"}, {"text": "Ja", "correct": false, "because": "Lokale Netze möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen einen Zugangspunkt sicher?', 4, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "SSID-Ausblendung", "correct": true, "because": "Erschwert Zugriff"}, {"text": "Hohe Reichweite", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Zugangspunkt immer öffentlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann privat sein"}, {"text": "Ja", "correct": false, "because": "Auch privat nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem mobilen Zugangspunkt?', 3, '[{"text": "Internet überall", "correct": true, "because": "Flexibler Zugriff"}, {"text": "Feste Verkabelung", "correct": false, "because": "Gegenteil von mobil"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Zugangspunkt nutzt WLAN. b) Er braucht immer 5G.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "5G nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für einen Zugangspunkt mit vielen Nutzern?', 4, '[{"text": "Wi-Fi 6", "correct": true, "because": "Höhere Kapazität"}, {"text": "Wi-Fi 4", "correct": false, "because": "Veraltet"}, {"text": "Bluetooth", "correct": false, "because": "Nicht geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Zugangspunkt ohne Passwort sicher ist?', 2, '[{"text": "Nein", "correct": true, "because": "Offen für Angriffe"}, {"text": "Ja", "correct": false, "because": "Schutz nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Reichweite bei einem Zugangspunkt?', 4, '[{"text": "Bestimmt Abdeckung", "correct": true, "because": "Definiert Nutzerbereich"}, {"text": "Erhöht Kosten", "correct": false, "because": "Nur indirekt"}, {"text": "Verkürzt Ladezeit", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt ein Zugangspunkt immer Ethernet?', 3, '[{"text": "Nein", "correct": true, "because": "Optional, nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Nicht immer enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem mobilen Zugangspunkt?', 4, '[{"text": "Reise mit Laptop", "correct": true, "because": "Flexibler Internetzugang"}, {"text": "Feste Büroinstallation", "correct": false, "because": "Nicht mobil"}, {"text": "Einzelgerät ohne WLAN", "correct": false, "because": "Braucht mehrere Nutzer"}]');
